import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { LucideIcon } from '@kerfjs/ui/lucide-icon';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { Inbox, Folder, Plus, Settings } from 'lucide';
import { delegate } from './events';
import './sidebar.css';

export function createNavigation(root: HTMLElement, paint: (html: ReturnType<typeof Toolbar>) => void, onAction: (action: string, id?: string) => void) {
  let selected = 'inbox';
  const render = () => <aside class="navigation app-root kui-layout">
    <nav class="kui-sidebar kui-scroll-owner kui-section-stack" aria-label="Workspace navigation">
      <section class="kui-sidebar-section"><MenuHeader label="Workspace" />
        <MenuItem action="workspace-navigate" itemId="inbox" label="Inbox" icon={<LucideIcon icon={Inbox} name="inbox" />} selected={selected === 'inbox'} />
        <MenuItem action="workspace-navigate" itemId="drafts" label="Drafts" selected={selected === 'drafts'} />
      </section>
      <section class="kui-sidebar-section"><MenuHeader label="Projects" />
        <MenuItem action="workspace-navigate" itemId="projects" label="Active projects" icon={<LucideIcon icon={Folder} name="folder" />} selected={selected === 'projects'} />
        <MenuItem action="workspace-navigate" itemId="archive" label="Archived — administrator access required" disabled multiline />
        <div class="kui-sidebar-surface"><strong>Workspace summary</strong><p>Three projects are ready for review.</p></div>
      </section>
    </nav>
    <footer><Toolbar label="Workspace actions" leading={<ToolbarControlGroup appearance="borderless" single><button type="button" aria-label="Add project" data-action="workspace-add"><LucideIcon icon={Plus} name="plus" /></button></ToolbarControlGroup>} trailing={<ToolbarControlGroup appearance="borderless" single><button type="button" aria-label="Workspace settings" data-action="workspace-settings"><LucideIcon icon={Settings} name="settings" /></button></ToolbarControlGroup>} /></footer>
  </aside>;
  const dispose = delegate(root, 'click', '[data-action]', element => {
    const action = element.dataset.action!;
    const id = element.dataset.itemId;
    if (action === 'workspace-navigate') {
      if (!id || !['inbox', 'drafts', 'projects'].includes(id)) return;
      selected = id;
      paint(render());
    }
    onAction(action, id);
  });
  paint(render());
  return { render, dispose };
}

